import { chromium } from "@playwright/test";

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on("pageerror", (e) => errors.push(`PAGEERROR: ${e.message.slice(0, 200)}`));
await page.goto("http://127.0.0.1:5173/editor/", {
  waitUntil: "domcontentloaded",
  timeout: 60000,
});
await page.waitForSelector("#twyne-editor-mount .ProseMirror", { timeout: 60000 });
await page.waitForTimeout(2000);

// Focus editor and type several paragraphs to force scrolling
await page.click("#twyne-editor-mount .ProseMirror");
for (let i = 0; i < 40; i++) {
  await page.keyboard.type(
    `Paragraph ${i}: The branch on Queen Street stays open until nine and the tables fill with readers. `,
  );
  await page.keyboard.press("Enter");
  await page.keyboard.press("Enter");
}
await page.waitForTimeout(1000);

// Caret visibility check
const caret = await page.evaluate(() => {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0) return { none: true };
  const r = sel.getRangeAt(0);
  const rect = r.getBoundingClientRect();
  const inPM = !!r.startContainer.parentElement?.closest(".ProseMirror");
  return {
    top: rect.top, bottom: rect.bottom,
    vh: window.innerHeight, inProseMirror: inPM,
    visible: rect.top >= 0 && rect.bottom <= window.innerHeight,
  };
});
console.log("CARET:", JSON.stringify(caret));

// Scroll container diagnostics
const scroll = await page.evaluate(() => {
  const pm = document.querySelector("#twyne-editor-mount .ProseMirror");
  const chain = [];
  let el = pm?.parentElement;
  while (el && chain.length < 8) {
    const cs = getComputedStyle(el);
    chain.push(`${el.tagName}.${(el.className.baseVal ?? el.className).toString().split(" ").slice(0, 3).join(".")} overflow=${cs.overflowY} scrollH=${el.scrollHeight} clientH=${el.clientHeight} scrollTop=${el.scrollTop}`);
    el = el.parentElement;
  }
  return chain;
});
console.log("SCROLL-CHAIN:\n" + scroll.join("\n"));

// Ctrl+A behaviour
await page.keyboard.press("Control+a");
await page.waitForTimeout(300);
const selInfo = await page.evaluate(() => {
  const sel = window.getSelection();
  const text = sel?.toString() ?? "";
  const anchorEl = sel?.anchorNode instanceof Element ? sel.anchorNode : sel?.anchorNode?.parentElement;
  const pm = document.querySelector("#twyne-editor-mount .ProseMirror");
  return {
    selLen: text.length,
    docLen: pm?.textContent?.length ?? -1,
    anchorInPM: !!anchorEl?.closest?.(".ProseMirror"),
    focusInPM: !!document.activeElement?.closest?.("#twyne-editor-mount"),
    activeTag: document.activeElement?.tagName,
  };
});
console.log("SELECT-ALL:", JSON.stringify(selInfo));
console.log("errors:", errors.length ? errors.slice(0, 8) : "none");
await page.screenshot({ path: "/tmp/opencode/editor-repro.png" });
await browser.close();

